-- Project ACX: transfer scrolls (wcid 50130) are named by spell school since 2026-11-27, "Item Transfer Scroll: Acid Bane VI"
-- (SpellTransferScroll.SchoolWord), so PackSort can move one school at a time. This renames the ones that already exist,
-- "Spell Transfer Scroll: X" -> "<School> Transfer Scroll: X", from each scroll's SpellDID (PropertyDataId 28).
-- School per spell id from the client DAT spell table. Run against ace_shard with the owners offline (then flush the
-- item cache, see NOTES); re-runnable: only names still starting "Spell Transfer Scroll: " change.
CREATE TEMPORARY TABLE acx_spell_school (id INT UNSIGNED PRIMARY KEY, word VARCHAR(8) NOT NULL);
