UPDATE biota_properties_string n
JOIN biota b ON b.id = n.object_Id AND b.weenie_Class_Id = 50130
JOIN biota_properties_d_i_d d ON d.object_Id = n.object_Id AND d.type = 28
JOIN acx_spell_school s ON s.id = d.value
SET n.value = CONCAT(s.word, ' Transfer Scroll: ', SUBSTRING(n.value, 24))
WHERE n.type = 1 AND n.value LIKE 'Spell Transfer Scroll: %';
DROP TEMPORARY TABLE acx_spell_school;
